<script setup lang="ts">
const state=useAtelier(),audio=useAudio(),{t,language}=useLocale(),settings=ref(false),about=ref(false)
function toggleSound(){state.sound.value=!state.sound.value;audio.click()}
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{}}
</script>
<template>
 <header class="header"><NuxtLink to="/" class="wordmark">VELOCITY 3<span>AUTOMOBILI</span></NuxtLink><nav><NuxtLink to="/">{{t('Обзор','Experience')}}</NuxtLink><NuxtLink to="/garage">{{t('Гараж','Garage')}} <sup>08</sup></NuxtLink><NuxtLink :to="'/drive/'+state.car.value.id">{{t('Поездка','Drive')}}</NuxtLink><button @click="about=true">{{t('О проекте','About')}}</button></nav><div class="header-tools"><button class="language-button" :aria-label="language==='ru'?'Switch to English':'Перевести на русский'" @click="language=language==='ru'?'en':'ru'">{{language==='ru'?'EN':'RU'}}</button><button @click="toggleSound" :aria-label="state.sound.value?t('Выключить звуки интерфейса','Mute interface sounds'):t('Включить звуки интерфейса','Enable interface sounds')">{{state.sound.value?'◖))':'◖×'}}</button><button :aria-label="t('Настройки','Settings')" @click="settings=true">⚙</button><button :aria-label="t('Полный экран','Fullscreen')" @click="fullscreen">⛶</button></div></header>
 <AtelierDialog v-if="settings" @close="settings=false"><small>VELOCITY 3 / {{t('ПАРАМЕТРЫ','PREFERENCES')}}</small><h2>{{t('Настройки','Settings')}}</h2><label>{{t('Качество графики','Graphics quality')}}<select v-model="state.quality.value"><option v-for="(q,i) in ['Low','Medium','High','Ultra']" :value="q">{{t(['Низкое','Среднее','Высокое','Ультра'][i]!,q)}}</option></select></label><label>{{t('Тени','Shadows')}}<input type="checkbox" v-model="state.shadows.value"></label><label>{{t('Анимация камеры','Camera animation')}}<input type="checkbox" v-model="state.motion.value"></label><label>{{t('Звуки интерфейса','Interface sounds')}}<input type="checkbox" v-model="state.sound.value" @change="audio.click()"></label><label>{{t('Громкость','Volume')}}<input type="range" min="0" max="1" step="0.01" v-model.number="state.volume.value" @change="audio.click()"></label><p>{{t('Звук — короткий отклик на нажатие. Звук двигателя включается отдельно в поездке и реагирует на газ и обороты. Качество графики меняет разрешение сцены и детализацию теней.','Sound is a brief interface click. Engine audio is enabled separately in Drive and responds to throttle and RPM. Graphics quality changes render resolution and shadow detail.')}}</p></AtelierDialog>
 <AtelierDialog v-if="about" @close="about=false"><small>{{t('НЕЗАВИСИМЫЙ ЦИФРОВОЙ ШОУРУМ','INDEPENDENT DIGITAL SHOWROOM')}}</small><h2>Velocity 3</h2><p>{{t('Рассмотрите автомобиль, выберите отделку, откройте двери и осмотрите салон с места водителя.','Explore the car, choose its finishes, open the doors and look around from the driver’s seat.')}}</p><p class="disclosure">{{t('Основная модель Ferrari 458 Italia — vicent091036, из примеров Three.js. Автомобили в Garage пока представлены прототипной геометрией. Проект не связан с производителями.','Ferrari 458 Italia model by vicent091036, from Three.js examples. The Garage collection currently uses prototype geometry. This project is not affiliated with the manufacturers.')}}</p></AtelierDialog>
